class FileManager:
    def __init__(self, filename, mode):
        self.filename = filename
        self.mode = mode
        self.file = None

    def __enter__(self):
        self.file = open(self.filename, self.mode)
        return self.file

    def __exit__(self, exc_type, exc_val, exc_tb):
        if self.file:
            self.file.close()
        return False

with FileManager('test.txt', 'w') as f:
    f.write('Hello, Context Manager!')

import sqlite3

class DatabaseConnection:
    def __init__(self, db_name):
        self.db_name = db_name
        self.conn = None

    def __enter__(self):
        self.conn = sqlite3.connect(self.db_name)
        return self.conn

    def __exit__(self, exc_type, exc_val, exc_tb):
        if self.conn:
            if exc_type is None:
                self.conn.commit()
            else:
                self.conn.rollback()
            self.conn.close()
        return False

with DatabaseConnection('app.db') as conn:
    conn.execute('CREATE TABLE IF NOT EXISTS test (id INTEGER)')
    conn.execute('INSERT INTO test VALUES (1)')

class FullLearningSystem(LearningTracker):
    def __init__(self, username):
        super().__init__(username)
        self.streak = 0
        self.last_study_date = None

    def daily_checkin(self):
        today = datetime.now().strftime('%Y-%m-%d')
        if self.last_study_date == today:
            print('今天已签到')
            return

        if self.last_study_date:
            last = datetime.strptime(self.last_study_date, '%Y-%m-%d')
            today_dt = datetime.strptime(today, '%Y-%m-%d')
            if (today_dt - last).days == 1:
                self.streak += 1
            else:
                self.streak = 1
        else:
            self.streak = 1

        self.last_study_date = today
        print(f'签到成功！连续{self.streak}天')

    def get_level(self):
        stats = self.get_stats()
        if stats['completed'] >= 10:
            return '大师'
        elif stats['completed'] >= 5:
            return '进阶'
        else:
            return '初学者'

